def recherche(tab, val):
    debut = 0
    fin = len(tab) - 1
    while debut <= fin:
        milieu = (debut + fin) // 2
        if tab[milieu] == val:
            return True
        elif tab[milieu] < val:
            debut = milieu + 1
        else:
            fin = milieu - 1
    return False

assert recherche([1, 5, 7, 9, 12, 13], 12)
assert not recherche([1, 5, 7, 9, 12, 13], 17)
